module dram_cell (
    input clk,
    input we,
    input reset,
    input [3:0] data_in,
    output reg [3:0] data_out
);
    reg [3:0] mem;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            mem <= 4'b0000;
            data_out <= 4'b0000;
        end else if (we) begin
            mem <= data_in;
            data_out <= data_in; // Output the written data
        end else begin
            data_out <= mem; // Output the stored data
        end
    end
endmodule

