module deserializer(  
    input wire clk,  
    input wire rst,  
    input wire serial_in,  
    output reg [15:0] parallel_out  
);  
    reg [3:0] count;  
    reg [15:0] shift_reg;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            count <= 4'b0;  
            shift_reg <= 16'b0;  
            parallel_out <= 16'b0;  
        end else begin  
            if (count < 16) begin  
                shift_reg <= {shift_reg[14:0], serial_in};  
                count <= count + 1;  
            end else begin  
                parallel_out <= shift_reg;  
                count <= 4'b0;  
                shift_reg <= 16'b0;  
            end  
        end  
    end  
endmodule

