module PID_Controller (
    input clk,
    input reset,
    input signed [15:0] setpoint,
    input signed [15:0] process_variable,
    output reg signed [15:0] control_signal
);
    reg signed [15:0] error;
    reg signed [15:0] previous_error;
    reg signed [15:0] integral;
    reg signed [15:0] derivative;

    parameter signed [15:0] Kp = 1;
    parameter signed [15:0] Ki = 1;
    parameter signed [15:0] Kd = 1;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            control_signal <= 0;
            previous_error <= 0;
            integral <= 0;
        end else begin
            error <= setpoint - process_variable;
            integral <= integral + error;
            derivative <= error - previous_error;
            control_signal <= Kp * error + Ki * integral + Kd * derivative;
            previous_error <= error;
        end
    end
endmodule

