module IIR_Filter (
    input wire clk,
    input wire rst,
    input wire signed [15:0] x_in,
    output reg signed [15:0] y_out
);
    // Coefficients (fixed point representation)
    parameter signed [15:0] b0 = 16'h2000; // 0.5 in fixed-point
    parameter signed [15:0] b1 = 16'h2000; // 0.5 in fixed-point
    parameter signed [15:0] a1 = 16'hF000; // -0.5 in fixed-point
    parameter signed [15:0] a2 = 16'h1000; // 0.25 in fixed-point

    reg signed [15:0] x1, x2; // Previous inputs
    reg signed [15:0] y1, y2; // Previous outputs

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y_out <= 0;
            x1 <= 0;
            x2 <= 0;
            y1 <= 0;
            y2 <= 0;
        end else begin
            // IIR Filter Equation
            y_out <= b0 * x_in + b1 * x1 + a1 * y1 + a2 * y2;
            // Shift the registers
            x2 <= x1;
            x1 <= x_in;
            y2 <= y1;
            y1 <= y_out;
        end
    end
endmodule

