module watchdog_timer (
    input wire clk,
    input wire trigger,
    output reg reset
);
    reg [1:0] counter;

    always @(posedge clk) begin
        if (trigger) begin
            reset <= 0;
            counter <= 0;
        end else begin
            if (counter < 2'b11) begin
                counter <= counter + 1;
            end else begin
                reset <= 1;
            end
        end
    end
endmodule

