module pll (
    input wire clk_ref,
    input wire feedback,
    input wire [1:0] control,
    output reg clk_out
);

    reg [1:0] phase_error;
    reg feedback_d;

    // Phase comparator
    always @(posedge clk_ref) begin
        feedback_d <= feedback;
        if (feedback_d == 1'b0 && feedback == 1'b1)
            phase_error <= 2'b01; // Phase locked
        else if (feedback_d == 1'b1 && feedback == 1'b0)
            phase_error <= 2'b10; // Out of phase
        else
            phase_error <= 2'b00; // No phase error
    end

    // Clock output generation based on control signal and phase error
    always @(posedge clk_ref) begin
        case (control)
            2'b00: clk_out <= clk_out; // Hold
            2'b01: clk_out <= ~clk_out; // Toggle
            2'b10: clk_out <= (phase_error == 2'b01) ? 1'b1 : 1'b0; // Lock to ref
            2'b11: clk_out <= (phase_error == 2'b10) ? 1'b0 : 1'b1; // Feedback
            default: clk_out <= 1'b0;
        endcase
    end
endmodule

