module phase_detector (  
    input clk_a,  
    input clk_b,  
    input rst,  
    output reg [1:0] phase_out  
);  
    reg [1:0] state;  

    always @(posedge clk_a or posedge rst) begin  
        if (rst)  
            state <= 2'b00;  
        else if (clk_b)  
            state <= 2'b00; // In phase  
        else  
            state <= 2'b01; // clk_a leads  
    end  

    always @(posedge clk_b or posedge rst) begin  
        if (rst)  
            phase_out <= 2'b00;  
        else if (clk_a)  
            phase_out <= 2'b10; // clk_b leads  
        else  
            phase_out <= state;  
    end  
endmodule

