module audio_sample_rate_converter (
    input clk,
    input reset,
    input [7:0] audio_in,
    output reg [7:0] audio_out,
    output reg valid_out
);
    reg [3:0] count; // Counts up to 44.1 (in simplified form, we'll use 44)
    reg [15:0] sum; // To accumulate the sum of the samples
    reg [4:0] avg_count; // Count for averaging

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            sum <= 0;
            avg_count <= 0;
            audio_out <= 0;
            valid_out <= 0;
        end else begin
            // Accumulate samples and count
            sum <= sum + audio_in;
            avg_count <= avg_count + 1;

            if (avg_count == 4'd43) begin // At 44 samples
                audio_out <= sum / 44; // Average and output
                valid_out <= 1; // Indicate valid output
                sum <= 0; // Reset sum for next batch
                avg_count <= 0; // Reset average count
            end else begin
                valid_out <= 0; // Until we reach 44, output is not valid
            end

            count <= count + 1; // Increment the sample count
        end
    end
endmodule

