module uart_transmitter (
    input wire clk,
    input wire start,
    input wire [7:0] data_in,
    output reg tx,
    output reg ready
);

    parameter BAUD_RATE = 9600;
    parameter CLOCK_FREQ = 50000000; // 50 MHz
    parameter PRESCALER = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] state;
    reg [3:0] bit_count;
    reg [15:0] counter;
    reg [7:0] shift_reg;

    localparam IDLE = 4'd0;
    localparam START_BIT = 4'd1;
    localparam DATA_BITS = 4'd2;
    localparam STOP_BIT = 4'd3;

    initial begin
        tx = 1'b1; // idle state is high
        ready = 1'b1;
        state = IDLE;
        counter = 0;
    end

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                tx <= 1;
                ready <= 1;
                if (start) begin
                    shift_reg <= data_in;
                    bit_count <= 0;
                    counter <= 0;
                    state <= START_BIT;
                    ready <= 0;
                end
            end
            START_BIT: begin
                if (counter < PRESCALER - 1) begin
                    counter <= counter + 1;
                end else begin
                    tx <= 0; // start bit
                    counter <= 0;
                    state <= DATA_BITS;
                end
            end
            DATA_BITS: begin
                if (counter < PRESCALER - 1) begin
                    counter <= counter + 1;
                end else if (bit_count < 8) begin
                    tx <= shift_reg[bit_count]; // send data bit
                    counter <= 0;
                    bit_count <= bit_count + 1;
                end else begin
                    counter <= 0;
                    state <= STOP_BIT;
                end
            end
            STOP_BIT: begin
                if (counter < PRESCALER - 1) begin
                    counter <= counter + 1;
                end else begin
                    tx <= 1; // stop bit
                    state <= IDLE;
                    ready <= 1; // ready for new data
                end
            end
        endcase
    end
endmodule

