module pipeline_processor(
    input clk,
    input [4:0] data_in,
    output reg [4:0] data_out
);
    reg [4:0] stage1, stage2, stage3, stage4, stage5, stage6, stage7;

    always @(posedge clk) begin
        // 1. Fetch
        stage1 <= data_in; // Output as is
        // 2. Decode
        stage2 <= ~stage1; // Invert bits
        // 3. Execute
        stage3 <= stage2 + 1; // Add 1
        // 4. Memory Access
        stage4 <= stage3 * 2; // Multiply by 2
        // 5. Write Back
        stage5 <= stage4 - 1; // Subtract 1
        // 6. Forwarding
        stage6 <= stage5 >> 1; // Divide by 2
        // 7. Output
        stage7 <= stage6; // Pass value to output
        data_out <= stage7; // Final Output
    end
endmodule

