module dma_controller (
    input clk,
    input rst,
    input [3:0] request,
    output reg [3:0] grant
);
    reg [1:0] current_channel;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            grant <= 4'b0000;
            current_channel <= 2'b00;
        end else begin
            if (request) begin
                grant <= 4'b0000; // Clear previous grant
                grant[current_channel] <= 1'b1; // Grant current channel
                // Update current channel for round-robin
                current_channel <= (current_channel + 1) % 4;
            end else begin
                grant <= 4'b0000; // No requests, no grant
            end
        end
    end
endmodule

