module turbo_decoder (
    input wire clk,
    input wire rst,
    input wire [1:0] encoded_input, // two input bits
    output reg decoded_output // single output bit
);

    reg [1:0] input_buffer; // buffer for the inputs

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            decoded_output <= 0;
            input_buffer <= 2'b00;
        end else begin
            input_buffer <= encoded_input;
            // Majority logic decoding
            if (input_buffer[0] + input_buffer[1] > 1) // if sum is greater than 1
                decoded_output <= 1;
            else
                decoded_output <= 0;
        end
    end
endmodule

module deadbeat_controller(
    input signed [3:0] current_state,
    output reg signed [3:0] control_signal
);
