        control_signal = -current_state; // For demonstration purposes
    end
endmodule

module vco #(parameter CLOCK_FREQ = 50_000_000) (  
    input wire clk,  
    input wire [2:0] control,  
    output reg out  
);  
    reg [31:0] counter;  
    reg [31:0] period;  

    always @(posedge clk) begin  
        if (control == 3'b000) begin  
            out <= 0;  
            counter <= 0;  
        end else begin  
            period <= (CLOCK_FREQ / (control + 1));  
            counter <= counter + 1;  
            if (counter >= period / 2) begin  
                out <= ~out;  
                counter <= 0;  
            end  
        end  
    end  
endmodule

