module pipelined_processor (
    input clk,
    input reset,
    input [31:0] instruction_in,
    output reg [31:0] reg_write_data,
    output reg [4:0] reg_write_addr,
    output reg write_enable
);

    reg [31:0] IF_ID_instr;
    reg [31:0] ID_EX_reg1, ID_EX_reg2, ID_EX_imm;
    reg [4:0] ID_EX_dst_reg;
    reg [31:0] EX_MEM_result;
    reg [4:0] EX_MEM_dst_reg;

    // Pipeline registers
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            IF_ID_instr <= 32'b0;
            ID_EX_reg1 <= 32'b0;
            ID_EX_reg2 <= 32'b0;
            ID_EX_imm <= 32'b0;
            ID_EX_dst_reg <= 5'b0;
            EX_MEM_result <= 32'b0;
            EX_MEM_dst_reg <= 5'b0;
            reg_write_data <= 32'b0;
            reg_write_addr <= 5'b0;
            write_enable <= 0;
        end else begin
            // Instruction Fetch Stage (IF)
            IF_ID_instr <= instruction_in;

            // Instruction Decode Stage (ID)
            ID_EX_reg1 <= IF_ID_instr[25:21]; // Assume source registers are in instruction
            ID_EX_reg2 <= IF_ID_instr[20:16];
            ID_EX_imm <= IF_ID_instr[15:0];
            ID_EX_dst_reg <= IF_ID_instr[15:11];

            // Execute Stage (EX)
            case (IF_ID_instr[31:26]) // opcode
                6'b000000: EX_MEM_result <= ID_EX_reg1 + ID_EX_reg2; // ADD
                6'b000001: EX_MEM_result <= ID_EX_reg1 - ID_EX_reg2; // SUB
                default: EX_MEM_result <= 32'b0;
            endcase
            EX_MEM_dst_reg <= ID_EX_dst_reg;

            // Memory Access Stage (MEM)
            // Assume no memory access for this simple example
            // Write Back Stage (WB)
            reg_write_data <= EX_MEM_result;
            reg_write_addr <= EX_MEM_dst_reg;
            write_enable <= 1; // Enable writing to register
        end
    end
endmodule

