module VCO (
    input wire clk,
    input wire rst,
    input wire [3:0] control_voltage,
    output reg square_wave,
    output reg [7:0] frequency
);
    reg [15:0] counter;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 0;
            square_wave <= 0;
            frequency <= 0;
        end else begin
            frequency <= control_voltage * 10; // Example conversion to frequency
            counter <= counter + 1;
            if (counter >= (50000 / frequency)) begin
                square_wave <= ~square_wave; // Toggle the square wave output
                counter <= 0;
            end
        end
    end
endmodule

