module i2c_master(
    input wire clk,
    input wire start,
    input wire stop,
    input wire [7:0] data_in,
    output reg sda,
    output reg scl,
    output reg ready
);

    reg [3:0] state;
    localparam IDLE     = 4'b0000,
               START    = 4'b0001,
               SEND_ADDR = 4'b0010,
               SEND_DATA = 4'b0011,
               STOP     = 4'b0100;

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                ready <= 1;
                if (start) begin
                    state <= START;
                    ready <= 0;
                end
            end
            START: begin
                sda <= 0; // Start condition
                scl <= 0;
                state <= SEND_ADDR;
            end
            SEND_ADDR: begin
                // Assuming 7-bit address + write bit (0)
                // Place the address on SDA, implement a simple shift register
                sda <= 7'b1010100; // Example address
                state <= SEND_DATA;
            end
            SEND_DATA: begin
                sda <= data_in; // Send data
                state <= STOP;
            end
            STOP: begin
                scl <= 1; // Generate stop condition
                sda <= 1; // Release SDA
                state <= IDLE;
            end
            default: state <= IDLE;
        endcase
    end
endmodule

