module rle_encoder (
    input clk,
    input rst,
    input bit_in,
    output reg [7:0] value_out,
    output reg [7:0] count_out,
    output reg valid
);
    reg [7:0] count;
    reg last_bit;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            last_bit <= 0;
            valid <= 0;
        end else begin
            if (bit_in == last_bit) begin
                count <= count + 1;
            end else begin
                if (count > 0) begin
                    value_out <= last_bit;
                    count_out <= count;
                    valid <= 1;
                end
                last_bit <= bit_in;
                count <= 1;
            end
        end
    end

    always @(posedge clk) begin
        if (valid) begin
            valid <= 0; // Clear valid after reading
        end
    end
endmodule

module rsa_encrypt (
    input [15:0] P,  // Plaintext input
    input [15:0] N,  // Modulus
    output [15:0] C  // Ciphertext output
);
    wire [31:0] P_cubed;
    wire [15:0] remainder;

    assign P_cubed = P * P * P; // P^3
    assign remainder = P_cubed % N; // C = P^3 mod N

    assign C = remainder;

endmodule

