module vco #(parameter FREQ_MIN = 1, parameter FREQ_MAX = 100)  
(  
    input wire clk,  
    input wire reset,  
    input wire [7:0] control_voltage,  
    output reg vco_out  
);  

    reg [31:0] counter;  
    reg [31:0] threshold;  

    always @(posedge clk or posedge reset)  
    begin  
        if (reset)  
        begin  
            vco_out <= 0;  
            counter <= 0;  
        end  
        else  
        begin  
            // Map control_voltage to frequency
            threshold <= (FREQ_MIN + (control_voltage * (FREQ_MAX - FREQ_MIN) / 255));  
            counter <= counter + 1;  

            if (counter >= threshold)  
            begin  
                vco_out <= ~vco_out;  
                counter <= 0;  
            end  
        end  
    end  
endmodule

