module watchdog_timer (  
    input wire clk,  
    input wire reset,  
    input wire start,  
    input wire feed,  
    output reg timeout  
);  
    parameter TIMEOUT_LIMIT = 4'b1010; // 10 clock cycles timeout  
    reg [3:0] counter;  
    reg timer_enabled;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            timeout <= 0;  
            counter <= 0;  
            timer_enabled <= 0;  
        end else if (start) begin  
            timer_enabled <= 1;  
            counter <= 0;  
            timeout <= 0;  
        end else if (timer_enabled) begin  
            if (feed) begin  
                counter <= 0;  
            end else begin  
                if (counter < TIMEOUT_LIMIT)  
                    counter <= counter + 1;  
                if (counter == TIMEOUT_LIMIT)  
                    timeout <= 1;  
            end  
        end  
    end  
endmodule

